## Why This Is Asked
Dynamic maximum XOR subset queries with deletions present a non-trivial challenge. An offline approach using interval decomposition elegantly handles deletions by converting them into active intervals.

## Key Concepts
- Time-segment tree over operation timeline
- Rollbackable linear basis for XOR operations
- Handling duplicates through separate active intervals

## Code Example

```javascript
class LinearBasis {
  constructor() { 
    this.b = new Array(32).fill(0); 
    this.history = [];
  }

  insert(x) {
    const original = [...this.b];
    this.history.push(original);

    for (let i = 31; i >= 0; i--) {
      if (!(x >> i) & 1) continue;
      if (!this.b[i]) {
        this.b[i] = x;
        break;
      }
      x ^= this.b[i];
    }
  }

  rollback() {
    this.b = this.history.pop();
  }

  maxXor() {
    let result = 0;
    for (let i = 31; i >= 0; i--) {
      result = Math.max(result, result ^ this.b[i]);
    }
    return result;
  }
}

class SegmentTree {
  constructor(n) {
    this.size = 1;
    while (this.size < n) this.size *= 2;
    this.tree = Array(2 * this.size).fill().map(() => []);
  }

  addInterval(l, r, value) {
    for (l += this.size, r += this.size; l < r; l >>= 1, r >>= 1) {
      if (l & 1) this.tree[l++].push(value);
      if (r & 1) this.tree[--r].push(value);
    }
  }

  process(queries) {
    const results = [];
    const basis = new LinearBasis();

    const dfs = (node, nodeL, nodeR) => {
      const saveHistorySize = basis.history.length;

      for (const value of this.tree[node]) {
        basis.insert(value);
      }

      if (nodeR - nodeL === 1) {
        results[nodeL] = basis.maxXor();
      } else {
        const mid = (nodeL + nodeR) / 2;
        dfs(node * 2, nodeL, mid);
        dfs(node * 2 + 1, mid, nodeR);
      }

      while (basis.history.length > saveHistorySize) {
        basis.rollback();
      }
    };

    dfs(1, 0, this.size);
    return results;
  }
}
```

## Update Rules
- Insert(x): Map to interval [time, ∞) until erase
- Erase(x): Close interval at current time
- Query: Process at leaf, gather basis maxXor result
- Rollback: Restore basis to previous state after subtree processing

## Complexity
- Build: O(n log n) for interval decomposition
- Process: O(32 log n) per query (32-bit basis × segment tree depth)
- Memory: O(n log n) for storing intervals in segment tree

This solution efficiently handles the dynamic nature with deletions by leveraging interval decomposition and rollback mechanisms, providing optimal query performance while maintaining clean separation of concerns.

## Why This Is Asked
Assesses practical use of an augmented BST (treap) to support ranking with duplicates in a live leaderboard setting.

## Key Concepts
- Treap with random priorities for balancing
- Node augmentation: subtree size for rank queries
- Key design: (score, playerId) to distinguish duplicates
- Rank query logic traversing by score threshold
- Handling time-evolving duplicates safely

## Code Example
```javascript
class LeaderboardTreap {
  constructor() { this.root = null; }
  _cmp(a, b) {
    if (a.score !== b.score) return a.score - b.score;
    return a.playerId.localeCompare(b.playerId);
  }
  _size(n) { return n ? n.size : 0; }
  _update(n) { if (n) n.size = 1 + this._size(n.left) + this._size(n.right); }
  _rotateLeft(p) {
    const r = p.right; p.right = r.left; r.left = p; this._update(p); this._update(r); return r;
  }
  _rotateRight(p) {
    const l = p.left; p.left = l.right; l.right = p; this._update(p); this._update(l); return l;
  }
  insertScore(playerId, score) {
    const key = { playerId, score, __prio: Math.random() };
    this.root = this._insert(this.root, key);
  }
  _insert(n, key) {
    if (!n) return { key, priority: key.__prio, left: null, right: null, size: 1 };
    if (this._cmp(key, n.key) < 0) {
      n.left = this._insert(n.left, key);
      if (n.left.priority > n.priority) n = this._rotateRight(n);
    } else {
      n.right = this._insert(n.right, key);
      if (n.right.priority > n.priority) n = this._rotateLeft(n);
    }
    this._update(n); return n;
  }
  eraseScore(playerId, score) {
    const key = { playerId, score };
    this.root = this._erase(this.root, key);
  }
  _erase(n, key) {
    if (!n) return null;
    const c = this._cmp(key, n.key);
    if (c < 0) { n.left = this._erase(n.left, key); }
    else if (c > 0) { n.right = this._erase(n.right, key); }
    else {
      if (!n.left) return n.right;
      if (!n.right) return n.left;
      if (n.left.priority > n.right.priority) { n = this._rotateRight(n); n.right = this._erase(n.right, key); }
      else { n = this._rotateLeft(n); n.left = this._erase(n.left, key); }
    }
    this._update(n); return n;
  }
  getRank(score) {
    const dfs = (n) => {
      if (!n) return 0;
      if (n.key.score <= score) return this._size(n.left) + 1 + dfs(n.right);
      return dfs(n.left);
    };
    return dfs(this.root);
  }
}
```

